"use client";

import { Badge } from "@/components/ui/badge";
import { Card, CardHeader, CardTitle } from "@/components/ui/card";
import { RunTable } from "./run-table";
import { CostChart } from "./cost-chart";
import type { Job, JobStatus, Run } from "@/lib/mock-data";

const statusBadge: Record<
  JobStatus,
  { variant: "success" | "error" | "info" | "neutral"; label: string }
> = {
  ok: { variant: "success", label: "Idle" },
  failed: { variant: "error", label: "Last Run Failed" },
  running: { variant: "info", label: "Running" },
  disabled: { variant: "neutral", label: "Idle" },
};

interface JobDetailProps {
  job: Job;
  runs: Run[];
  onSelectRun: (runId: string) => void;
}

export function JobDetail({ job, runs, onSelectRun }: JobDetailProps) {
  const badge = statusBadge[job.status];
  const jobRuns = runs.filter((r) => r.jobId === job.id);

  // Compute total cost from loaded runs
  const totalCost = jobRuns.reduce((sum, r) => {
    if (r.cost && r.cost !== "--") {
      return sum + (parseFloat(r.cost.replace("$", "")) || 0);
    }
    return sum;
  }, 0);

  return (
    <div className="flex-1 overflow-y-auto p-6 space-y-6">
      {/* Header row */}
      <div className="flex items-center gap-3">
        <h1 className="text-xl font-semibold text-text-primary">{job.name}</h1>
        <Badge variant={badge.variant}>{badge.label}</Badge>
        <span className="text-[11px] text-text-secondary/50">|</span>
        {job.enabled ? (
          <span className="text-[11px] text-success/70 font-medium">Enabled</span>
        ) : (
          <span className="text-[11px] text-text-secondary/40 font-medium">Disabled</span>
        )}
      </div>

      {/* Widget row: cost chart (2/3) + metrics (1/3) */}
      <div className="grid grid-cols-3 gap-4">
        {/* Cost per run chart - 2/3 width */}
        <Card className="col-span-2 p-4">
          <div className="flex items-center justify-between mb-2">
            <span className="text-[10px] font-medium text-text-secondary uppercase tracking-wider">
              Cost per Run
            </span>
            <span className="text-[10px] text-text-secondary/40 font-mono">
              Last {Math.min(jobRuns.filter((r) => r.cost && r.cost !== "--").length, 8)} runs
            </span>
          </div>
          <div className="h-32">
            <CostChart runs={jobRuns} />
          </div>
        </Card>

        {/* Metrics - 1/3 width */}
        <div className="flex flex-col gap-3">
          {/* Total cost */}
          <Card className="p-4 flex-1 flex flex-col justify-center">
            <span className="text-[10px] font-medium text-text-secondary uppercase tracking-wider">
              Total Cost
            </span>
            <p className="text-2xl font-semibold text-text-primary tracking-tight mt-1">
              ${totalCost.toFixed(2)}
            </p>
            <span className="text-[10px] text-text-secondary/40 mt-0.5">
              {jobRuns.length} loaded run{jobRuns.length !== 1 ? "s" : ""}
            </span>
          </Card>

          {/* Next run */}
          <Card className="p-4 flex-1 flex flex-col justify-center">
            <span className="text-[10px] font-medium text-text-secondary uppercase tracking-wider">
              Next Run
            </span>
            {job.nextRun ? (
              <>
                <p className="text-lg font-semibold text-primary tracking-tight mt-1">
                  {job.nextRun}
                </p>
                <span className="text-[10px] text-text-secondary/40 font-mono mt-0.5">
                  {job.schedule}
                </span>
              </>
            ) : (
              <p className="text-sm text-text-secondary/40 mt-1">
                Not scheduled
              </p>
            )}
          </Card>
        </div>
      </div>

      {/* Run History */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <CardTitle>Run History</CardTitle>
            <span className="text-[11px] text-text-secondary/50 font-mono">
              {jobRuns.length} run{jobRuns.length !== 1 ? "s" : ""}
            </span>
          </div>
        </CardHeader>
        {jobRuns.length === 0 ? (
          <p className="text-sm text-text-secondary">No runs yet.</p>
        ) : (
          <RunTable runs={jobRuns} onSelectRun={onSelectRun} />
        )}
      </Card>
    </div>
  );
}
