"use client";

import { useState } from "react";
import { cn } from "@/lib/utils";
import type { Run } from "@/lib/mock-data";

const timeRanges = [
  { label: "1W", days: 7 },
  { label: "2W", days: 14 },
  { label: "1M", days: 30 },
  { label: "3M", days: 90 },
  { label: "All", days: Infinity },
] as const;

interface CostChartProps {
  runs: Run[];
}

export function CostChart({ runs }: CostChartProps) {
  const [range, setRange] = useState<string>("All");

  const selectedRange = timeRanges.find((r) => r.label === range) ?? timeRanges[4];

  // Use the most recent run's date as "now" so mock data always works
  const allDates = runs
    .map((r) => new Date(r.started.replace(" ", "T")).getTime())
    .filter((t) => !isNaN(t));
  const refTime = allDates.length > 0 ? Math.max(...allDates) : Date.now();

  // Filter runs by time range and cost availability
  const costData = runs
    .filter((r) => {
      if (!r.cost || r.cost === "--") return false;
      const parsed = parseFloat(r.cost.replace("$", ""));
      if (isNaN(parsed) || parsed === 0) return false;
      if (selectedRange.days === Infinity) return true;
      const started = new Date(r.started.replace(" ", "T")).getTime();
      if (isNaN(started)) return false;
      const diffDays = (refTime - started) / 86400000;
      return diffDays <= selectedRange.days;
    })
    .slice(0, 10)
    .reverse()
    .map((r) => ({
      id: r.id.length > 8 ? r.id.slice(0, 6) : r.id,
      cost: parseFloat(r.cost.replace("$", "")),
      date: r.started.split(" ")[0]?.slice(5) || "",
    }));

  const max = costData.length > 0 ? Math.max(...costData.map((d) => d.cost)) : 0;

  return (
    <div className="flex flex-col h-full">
      {/* Time range filters */}
      <div className="flex items-center gap-1 mb-2">
        {timeRanges.map((r) => (
          <button
            key={r.label}
            onClick={() => setRange(r.label)}
            className={cn(
              "px-2 py-0.5 rounded text-[10px] font-medium transition-colors cursor-pointer",
              range === r.label
                ? "bg-primary/15 text-primary"
                : "text-text-secondary/50 hover:text-text-secondary hover:bg-surface-elevated"
            )}
          >
            {r.label}
          </button>
        ))}
      </div>

      {/* Bar Chart */}
      {costData.length === 0 || max === 0 ? (
        <div className="flex-1 flex items-center justify-center text-xs text-text-secondary/40">
          No cost data for this period
        </div>
      ) : (
        <div className="flex items-end gap-1.5 flex-1 min-h-0">
          {costData.map((d, i) => {
            const heightPct = (d.cost / max) * 100;
            const isMax = d.cost === max;
            return (
              <div
                key={i}
                className="flex flex-col items-center flex-1 min-w-0 h-full"
              >
                {/* Cost label */}
                <span className="text-[10px] font-mono text-text-secondary/50 mb-1 truncate w-full text-center">
                  ${d.cost.toFixed(2)}
                </span>
                {/* Bar container */}
                <div className="flex-1 w-full flex items-end">
                  <div
                    className="w-full rounded-t-sm"
                    style={{
                      height: `${Math.max(heightPct, 6)}%`,
                      backgroundColor: isMax
                        ? "var(--primary)"
                        : "color-mix(in oklch, var(--primary), transparent 60%)",
                    }}
                  />
                </div>
                {/* Date label */}
                <span className="text-[10px] font-mono text-text-secondary/30 mt-1 truncate w-full text-center">
                  {d.date}
                </span>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}
