"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { ExclamationTriangleIcon, XMarkIcon } from "@heroicons/react/20/solid";

interface DeleteDialogProps {
  jobName: string;
  onConfirm: () => void;
  onCancel: () => void;
}

export function DeleteDialog({ jobName, onConfirm, onCancel }: DeleteDialogProps) {
  const [typed, setTyped] = useState("");
  const matches = typed === jobName;

  return (
    /* Backdrop */
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      <div
        className="absolute inset-0 bg-black/60 backdrop-blur-sm"
        onClick={onCancel}
      />

      {/* Dialog */}
      <div className="relative z-10 w-full max-w-md rounded-2xl bg-surface-elevated p-6 shadow-[var(--shadow-elevated)]">
        {/* Close button */}
        <button
          onClick={onCancel}
          className="absolute right-4 top-4 text-text-secondary hover:text-text-primary transition-colors cursor-pointer"
          aria-label="Close"
        >
          <XMarkIcon className="h-5 w-5" />
        </button>

        {/* Icon + title */}
        <div className="flex items-start gap-3 mb-4">
          <div className="flex h-10 w-10 flex-shrink-0 items-center justify-center rounded-full bg-error/15">
            <ExclamationTriangleIcon className="h-5 w-5 text-error" />
          </div>
          <div>
            <h2 className="text-lg font-semibold text-text-primary">
              Delete Job
            </h2>
            <p className="text-sm text-text-secondary mt-1">
              This action cannot be undone. This will permanently delete the job{" "}
              <span className="font-mono font-semibold text-text-primary">
                {jobName}
              </span>{" "}
              and all its run history.
            </p>
          </div>
        </div>

        {/* Confirmation input */}
        <div className="mb-5">
          <label className="block text-xs font-medium text-text-secondary mb-1.5">
            Type <span className="font-mono text-text-primary">{jobName}</span>{" "}
            to confirm
          </label>
          <input
            type="text"
            value={typed}
            onChange={(e) => setTyped(e.target.value)}
            placeholder="Type job name to confirm"
            className="w-full rounded-lg border border-border bg-surface-elevated/60 px-3 py-2.5 text-sm font-mono text-text-primary placeholder:text-text-secondary/40 outline-none focus:border-error/40 focus:ring-1 focus:ring-error/20 transition-colors"
            autoFocus
          />
        </div>

        {/* Actions */}
        <div className="flex items-center justify-end gap-3">
          <Button variant="secondary" size="sm" onClick={onCancel}>
            Cancel
          </Button>
          <Button
            variant="destructive"
            size="sm"
            disabled={!matches}
            onClick={onConfirm}
          >
            Delete Job
          </Button>
        </div>
      </div>
    </div>
  );
}
